                html += `<span class="label">Current:</span> ${currentOpcode.toString(16).toUpperCase().padStart(4, '0')} ($${hexByte.toString(16).toUpperCase()})<br>`;
                html += `<span class="label">Hex Byte:</span> $${hexByte.toString(16).toUpperCase()}<br>`;

                // Instruction decoding
                const decoded = this.decodeInstruction(currentOpcode, hexByte, lowerNibble, upperNibble);
                if (decoded) {
                    html += `<span class="label">Decoded:</span> ${decoded}<br>`;
                }

                // Stack
                html += '<div class="debug-section">';
                html += '<span class="label">Stack:</span> ';
                for (let i = 0; i < this.stack.length; i++) {
                    html += `${this.stack[i].toString().padStart(2, '0')} `;
                }
                if (this.stack.length === 0) {
                    html += '(empty)';
                }
                html += '</div>';

                // Timers
                html += '<div class="debug-section">';
                html += `<span class="label">Delay:</span> ${this.delayTimer}<br>`;
                html += `<span class="label">Sound:</span> ${this.soundTimer}`;
                html += '</div>';

                // Collision flag
                html += '<div class="debug-section">';
                html += `<span class="label">Collision:</span> ${this.collisionFlag ? 'Yes' : 'No'}`;
                html += '</div>';

                html += '</div>';
                panel.innerHTML = html;
            }

            decodeInstruction(opcode, hexByte, lowerNibble, upperNibble) {
                const x = this.registers[0] & 0x0F;
                const y = this.registers[1] & 0x0F;

                switch (hexByte) {
                    case 0: return `CLR`;
                    case 1: return `JP $${opcode.toString(16).toUpperCase().padStart(4, '0')}`;
                    case 2: return `CALL $${opcode.toString(16).toUpperCase().padStart(4, '0')}`;
                    case 3: return `SE V${x},$${lowerNibble}`;
                    case 4: return `SE V${x},V${y}`;
                    case 5: return `SE V${x},${upperNibble}${lowerNibble}`;
                    case 6: return `LD V${x},$${lowerNibble.toString(16).toUpperCase()}`;
                    case 7: return `ADD V${x},$${lowerNibble}`;
                    case 8: {
                        switch (lowerNibble) {
                            case 0: return `LD V${x},V${y}`;
                            case 1: return `OR V${x},V${y}`;
                            case 2: return `AND V${x},V${y}`;
                            case 3: return `XOR V${x},V${y}`;
                            case 4: return `ADD V${x},V${y} VF`;
                            case 5: return `SUB V${x},V${y} VF`;
                            case 6: return `SHR V${x}>> VF`;
                            case 7: return `SUBN V${x},V${y} VF`;
                            case 8: return `LD V${x},0`;
                            case 9: return `LD V${x},VF`;
                            case 15: return `?`;
                        }
                    }
                    case 9: return `SE V${x},V${y}`;
                    case 10: return `ADD I,V${y}`;
                    case 14: return `LD V${x},I+VF`;
                    case 15: {
                        if (upperNibble === 1) return `SKP $${lowerNibble}`;
                        if (upperNibble === 2) return `NKY $${lowerNibble}`;
                        break;
                    }
                    case 16: return `LD I,V${y}`;
                    case 17: return `JP V0,$${opcode.toString(16).toUpperCase().padStart(4, '0')}`;
                    case 23: return `RDY`;
                    case 24: return `?`;
                }

                return '';
            }

            getDebuggerHTML() {
                const panel = document.getElementById('debugPanel');
                return panel.innerHTML;
            }

            stop() {
                this.paused = true;
                alert(`Key not pressed! Press key ${this.keyState.indexOf(1) >= 0 ? (this.keyState.indexOf(1).toString()) : 'any'} to continue.`);
            }
        }

        // Initialize emulator
        const emulator = new CHIP8();

        // Set up keypad buttons
        document.querySelectorAll('.keypad button').forEach(button => {
            button.addEventListener('mousedown', () => {
                const key = parseInt(button.dataset.key);
                emulator.handleKeyPress({ code: 'Key' + key, key: key }, true);
            });

            button.addEventListener('mouseup', () => {
                const key = parseInt(button.dataset.key);
                emulator.handleKeyPress({ code: 'Key' + key, key: key }, false);
            });

            button.addEventListener('mouseleave', () => {
                const key = parseInt(button.dataset.key);
                emulator.handleKeyPress({ code: 'Key' + key, key: key }, false);
            });
        });

        // ROM loader
        document.getElementById('romLoader').addEventListener('change', (e) => {
            if (e.target.files.length > 0) {
                emulator.loadFile(e.target.files[0]);
            }
        });

        // Expose methods globally
        window.emulator = emulator;
    </script>
</body>
</html>
